        args = typ.__args__ if hasattr(typ, "__args__") else ()
        elem_types = [type_to_dict(arg) for arg in args]
        return {
            "module": "typing",
            "qualname": "Union",
            "elem_types": elem_types,
        }
    if is_generic(typ):
        if hasattr(typ, "__origin__"):
            origin = typ.__origin__
            if hasattr(origin, "__name__"):
                qualname = origin.__name__
            else:
                qualname = qualname_of_generic(typ)
            elem_types = []
            if hasattr(typ, "__args__") and typ.__args__ is not None:
                elem_types = [type_to_dict(arg) for arg in typ.__args__]
            return {
                "module": origin.__module__,
                "qualname": qualname,
                "elem_types": elem_types,
            }
        else:
            return {
                "module": typ.__module__,
                "qualname": typ.__qualname__,
            }
    return {
        "module": typ.__module__,
        "qualname": typ.__qualname__,
    }
